/*
 * A201853  Primes of the form 7n^2 - 8.
 * https://oeis.org/A201853
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 13, u32 n <= 1640, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Validated: standard, pass, 48 terms through n = 4834 (2026-11-03)
 * Helpers:   is_prime_u128, is_prime_u64, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: primes of the form 7*n^2 - 8, generated by brute force search. */

#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <limits.h>
#include "../utils/is_prime_u128.h"
#include "../utils/is_prime_u64.h"
#include "../utils/mem.h"

/* -----------------  Generic primality test ------------------------ */
static bool isPrimeGeneric(seq_t n)
{
    /* all seq_t are unsigned; use the smallest type that fits */
    if ((seq_t)(ULLONG_MAX) >= n) {
        return is_prime_u64((uint64_t)n);
    }
#if defined(__SIZEOF_INT128__)
    return is_prime_u128((__uint128_t)n);
#else
    /* fallback: if seq_t > 64‑bit but no 128‑bit support,
       order the test as simple trial division up to sqrt */
    seq_t limit = 0;
    for (seq_t i = 2; i*i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
#endif
}

/* Cache for computed sequence values. */
static seq_t *cache = NULL;
static size_t  cache_cap = 0;
static size_t  cache_len = 0;

/* The next integer n to test in the polynomial 7*n^2 - 8. */
static idx_t next_test_n = 1;

/* Ensure the cache has enough capacity to hold `needed` elements. */
static void ensure_cache_capacity(size_t needed)
{
    if (needed <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    if (new_cap < needed)
        new_cap = needed;
    seq_t *tmp = mem_resize(seq_t, cache, new_cap);
    if (!tmp) {
        /* If reallocation fails, abort the program – no recovery path. */
        abort();
    }
    cache = tmp;
    cache_cap = new_cap;
}

/* Return the nth term (1‑based) of the sequence. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;          /* behaviour for indices before the offset is irrelevant */

    /* Generate elements until we have at least n of them. */
    while (cache_len < (size_t)n) {
        /* Compute candidate p = 7*next_test_n^2 - 8. */
        seq_t pn2 = (seq_t)next_test_n * (seq_t)next_test_n;   /* n^2  */
        seq_t candidate = (seq_t)7 * pn2 - (seq_t)8;            /* 7n^2 - 8 */

        /* Check primality. */
        if (isPrimeGeneric(candidate)) {
            ensure_cache_capacity(cache_len + 1);
            cache[cache_len++] = candidate;
        }
        next_test_n++;
    }

    return cache[n - 1];
}
